using System.Runtime.InteropServices;

class EnvVarCheck
{
    // Checks whether an env var is defined on Unix (even if empty)
    // by reading /proc/self/environ, since .NET 9 treats "" as unset.
    static bool CheckEnvVarExistsUnix(string name)
    {
        try
        {
            var environ = File.ReadAllText("/proc/self/environ");
            return environ.Split('\0').Any(e => e == name + "=" || e.StartsWith(name + "="));
        }
        catch
        {
            return Environment.GetEnvironmentVariable(name) != null;
        }
    }

    void CheckFlag()

